import {itemById} from './project-options.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function attachmentsMarkup(project,editable=false) {
 const files=project.attachments||[];
 return `<section class="client-attachments"><h3>Planta e fotografias do cliente</h3><p class="field-description">A planta enviada e os pedidos ficam na ficha para validação. O modelo 3D mantém a distribuição seleccionada.</p>${editable?`<div class="attachment-upload"><label class="project-field"><span>Carregar planta definida pelo cliente</span><input type="file" data-client-upload="plan" accept="image/png,image/jpeg,application/pdf" ${files.some(f=>f.kind==='plan')?'disabled':''}><small>PNG, JPEG ou PDF · até 5 MB · PDF até 20 páginas. Retire a planta actual para a substituir.</small></label><label class="project-field"><span>Adicionar fotografias de referência</span><input type="file" data-client-upload="photo" multiple accept="image/png,image/jpeg"><small>PNG ou JPEG · até 5 MB por fotografia · 12 anexos e 20 MB no total.</small></label></div>`:''}<div class="client-attachment-list">${files.map(file=>`<article class="client-attachment" data-attachment="${file.id}"><strong>${file.kind==='plan'?'Planta do cliente':'Fotografia de referência'} · ${esc(file.name)}</strong>${file.mime==='application/pdf'?'<p>Planta PDF · todas as páginas serão incluídas no dossier.</p>':`<img src="${file.dataUrl}" alt="${esc(file.name)}" loading="lazy">`}${editable?`<label class="project-field"><span>Observação · ${esc(file.name)}</span><textarea rows="3" maxlength="2400" data-attachment-note="${file.id}">${esc(file.notes)}</textarea></label>`:`<p class="client-preserve-lines">${esc(file.notes||'Sem observações.')}</p>`}<button class="outline" data-download-attachment="${file.id}">Descarregar original</button>${editable?`<button class="text-link" data-remove-attachment="${file.id}" aria-label="Retirar ${esc(file.name)}">Retirar anexo</button>`:''}</article>`).join('')}</div>${!files.length?'<p class="field-description">Ainda não foram adicionadas plantas ou fotografias.</p>':''}</section>`;
}
export function requestsMarkup(project,editable=false) {
 return `<section class="client-requests"><h3>Pedidos específicos do cliente</h3><p class="field-description">Registe janelas novas, alterações e extras que ainda não têm lugar no 3D. Cada pedido fica sob cotação e não é somado ao subtotal. Para artigos com preço publicado, escolha primeiro o artigo em Adicionais.</p>${(project.requests||[]).map(request=>`<article class="client-request" data-request="${request.id}">${editable?`<label class="project-field"><span>Descrição do pedido</span><input data-request-field="title" data-request-id="${request.id}" maxlength="160" value="${esc(request.title)}"></label><label class="project-field"><span>Quantidade</span><input type="number" min="1" max="99" step="1" data-request-field="quantity" data-request-id="${request.id}" value="${request.quantity}"></label><label class="project-field"><span>Divisão ou local pretendido</span><input data-request-field="location" data-request-id="${request.id}" maxlength="160" value="${esc(request.location)}"></label><label class="project-field"><span>Medidas e observações</span><textarea rows="3" maxlength="2400" data-request-field="notes" data-request-id="${request.id}">${esc(request.notes)}</textarea></label><button class="text-link" data-remove-request="${request.id}">Retirar pedido</button>`:`<strong>${request.quantity} × ${esc(request.title||'Pedido por descrever')}</strong><p>${esc(request.location||'Local por definir')}</p><p class="client-preserve-lines">${esc(request.notes)}</p>`}<p><strong>Sob cotação · validação técnica pendente</strong></p></article>`).join('')}${editable?'<button class="outline" data-add-request="window">Pedir janela extra na cozinha</button><button class="outline" data-add-request="other">Acrescentar outro pedido</button>':''}</section>`;
}
export function optionNotesMarkup(project,state) {
 return (state.optionSelections||[]).filter(item=>project.optionNotes?.[item.id]).map(item=>`<p class="client-preserve-lines"><strong>${esc(itemById(item.id)?.label||item.id)} · local e observações:</strong> ${esc(project.optionNotes[item.id])}</p>`).join('');
}
